## Why This Is Asked
Tests bridging a C object with Go, memory ownership, and safe cross-language concurrency using CGO. It also touches resource lifecycle (Close) and error handling when C returns NULL.

## Key Concepts
- CGO bindings for C structs and lifecycle
- Memory ownership and Free/Close semantics
- Thread-safety in C with a mutex vs. Go-level synchronization
- Cross-language error handling and result propagation

## Code Example
```c
// counter.h
typedef struct AtomicCounter AtomicCounter;
AtomicCounter* ac_new(void);
void ac_inc(AtomicCounter* ac);
int ac_get(AtomicCounter* ac);
void ac_free(AtomicCounter* ac);
```
```c
// counter.c (stub with mutex)
#include <stdlib.h>
#include <pthread.h>
typedef struct AtomicCounter {
  int val;
  pthread_mutex_t m;
} AtomicCounter;
AtomicCounter* ac_new(void){ AtomicCounter* a = malloc(sizeof(AtomicCounter)); a->val=0; pthread_mutex_init(&a->m, NULL); return a; }
void ac_inc(AtomicCounter* a){ pthread_mutex_lock(&a->m); a->val++; pthread_mutex_unlock(&a->m); }
int ac_get(AtomicCounter* a){ pthread_mutex_lock(&a->m); int v=a->val; pthread_mutex_unlock(&a->m); return v; }
void ac_free(AtomicCounter* a){ pthread_mutex_destroy(&a->m); free(a); }
```
```go
// counter.go
package counter
/*
#include "counter.h"
#include <stdlib.h>
*/
import "C"
import (
  "errors"
)

type AtomicCounter struct{ c *C.AtomicCounter }

func NewAtomicCounter() (*AtomicCounter, error) {
  p := C.ac_new()
  if p == nil {
    return nil, errors.New("failed to create AtomicCounter")
  }
  return &AtomicCounter{c: p}, nil
}

func (a *AtomicCounter) Inc() { C.ac_inc(a.c) }
func (a *AtomicCounter) Get() int { return int(C.ac_get(a.c)) }
func (a *AtomicCounter) Close() { C.ac_free(a.c) }
```

```go
// main.go
package main
import (
  "fmt"
  "sync"
  "counter" // path to the package
)

func main() {
  ac, _ := counter.NewAtomicCounter()
  var wg sync.WaitGroup
  increments := 1000
  for i := 0; i < 3; i++ {
    wg.Add(1)
    go func() {
      for j := 0; j < increments; j++ { ac.Inc() }
      wg.Done()
    }()
  }
  wg.Wait()
  fmt.Println("final:", ac.Get())
  ac.Close()
}
```

## Follow-up Questions
- How would you support multiple independent counters in the same process?
- What changes to CGO flags or build tags would you add to ensure pthreads compatibility on all platforms?

## Why This Is Asked
Tests practical CGOA memory ownership and error propagation with a non-trivial parser and a streaming Go consumer.

## Key Concepts
- CGO memory ownership across boundaries
- Safe conversion of C strings to Go strings
- Properly freeing C-allocated memory
- Basic tokenizer with quotes/escapes

## Code Example
```c
// header: tokenizer.h
int tokenize_line(const char* line, char*** tokens, size_t* n);
void free_tokens(char** tokens, size_t n);
```
```c
#include <stdlib.h>
#include <string.h>
#include <tokenizer.h>

int tokenize_line(const char* line, char*** tokens, size_t* n){
  if(!line) return -1;
  const char* p = line;
  size_t cap = 8, i = 0;
  char** toks = (char**)malloc(cap*sizeof(char*));
  while(*p){
    while(*p==' ') p++;
    if(!*p) break;
    const char* start = p;
    int inq = 0;
    while(*p){
      if(*p=='"') inq = !inq;
      else if(*p==' ' && !inq) break;
      p++;
    }
    size_t len = p-start;
    char* t = (char*)malloc(len+1);
    memcpy(t, start, len);
    t[len] = '\0';
    if(i==cap){ cap*=2; toks=(char**)realloc(toks, cap*sizeof(char*)); }
    toks[i++] = t;
  }
  *tokens = toks; *n = i; return 0;
}

void free_tokens(char** tokens, size_t n){
  if(!tokens) return; for(size_t i=0;i<n;i++){ free(tokens[i]); } free(tokens);
}
```
```go
package tokenizer
/*
#include <tokenizer.h>
#include <stdlib.h>
*/
import "C"
import (
  "errors"
  "unsafe"
)

func TokenizeLine(line string) ([]string, error) {
  cLine := C.CString(line)
  defer C.free(unsafe.Pointer(cLine))
  var cTokens **C.char
  var n C.size_t
  if code := C.tokenize_line(cLine, &cTokens, &n); code != 0 {
    return nil, errors.New("tokenization failed")
  }
  count := int(n)
  toks := make([]string, 0, count)
  slice := (*[1<<30]*C.char)(unsafe.Pointer(cTokens))[:count:count]
  for _, cstr := range slice {
    toks = append(toks, C.GoString(cstr))
  }
  C.free_tokens(cTokens, n)
  return toks, nil
}
```
```go
package main
import (
  "bufio"
  "fmt"
  "os"
  "sync/atomic"
  t "./tokenizer"
)
func main(){
  in := bufio.NewScanner(os.Stdin)
  var total, lines uint64
  for in.Scan(){
    line := in.Text()
    tokens, err := t.TokenizeLine(line)
    if err != nil { fmt.Println("err:", err); continue }
    atomic.AddUint64(&lines, 1)
    atomic.AddUint64(&total, uint64(len(tokens)))
    fmt.Println(tokens)
  }
}
```

